-- ************************************** SUPPLYCHAIN.VIEW_1
CREATE VIEW SUPPLYCHAIN.VIEW_1
(
  MAINTENANCEID COMMENT 'Unique identifier for the maintenance activity',
  MAINTENANCEDATE COMMENT 'Date when the maintenance was performed',
  MAINTENANCETYPE COMMENT 'Type of maintenance activity',
  MAINTENANCECOST COMMENT 'Cost associated with the maintenance',
  MAINTENANCEDURATIONHOURS COMMENT 'Duration of the maintenance activity in hours',
  WAREHOUSEZONE COMMENT 'Name of the warehouse zone where maintenance was performed',
  ZONEFUNCTION COMMENT 'Primary function of the warehouse zone',
  WAREHOUSENAME COMMENT 'Name of the warehouse',
  ADDRESS COMMENT 'Street address of the warehouse',
  CITY COMMENT 'City where the warehouse is located',
  STATE COMMENT 'State where the warehouse is located',
  COUNTRY COMMENT 'Country where the warehouse is located'
)
COMMENT = 'View providing warehouse maintenance details with zone and location information for maintenance analysis and operational reporting.'
AS
(
  SELECT 
    wm.MaintenanceID,
    wm.DateKey AS MaintenanceDate,
    wm.MaintenanceType,
    wm.MaintenanceCost,
    wm.MaintenanceDurationHours,
    wz.ZoneName AS WarehouseZone,
    wz.ZoneFunction,
    w.WarehouseName,
    w.Address,
    w.City,
    w.State,
    w.Country
  FROM 
    WarehouseMaintenanceFact wm
  INNER JOIN Warehouse w
    ON wm.WarehouseKey = w.WarehouseID
  INNER JOIN WarehouseZoneDim wz
    ON w.WarehouseID = wz.WarehouseKey
);

